package com.playercoder1.chess;

import java.util.Objects;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.RejectedExecutionException;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.audio.AudioPlayer;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Singleton
public final class ChessSoundService implements ChessGameListener
{
    private static final Logger LOG = LoggerFactory.getLogger(ChessSoundService.class);
    private static final float SOUND_GAIN_DB = 0.0f;

    private enum Sound
    {
        MOVE("/move-self.wav"),
        CAPTURE("/capture.wav"),
        CASTLE("/castle.wav"),
        CHECK("/move-check.wav"),
        PROMOTION("/promote.wav"),
        GAME_END("/game-end.wav");

        private final String resourcePath;

        Sound(String resourcePath)
        {
            this.resourcePath = resourcePath;
        }
    }

    private final LocalChessController controller;
    private final AudioPlayer audioPlayer;

    private ExecutorService executor;
    private String previousFen;
    private String previousLastMove;
    private GameStatus previousStatus;
    private boolean started;
    private boolean playbackFailureLogged;

    @Inject
    public ChessSoundService(LocalChessController controller, AudioPlayer audioPlayer)
    {
        this.controller = controller;
        this.audioPlayer = audioPlayer;
    }

    public synchronized void start()
    {
        if (started)
        {
            return;
        }

        executor = Executors.newSingleThreadExecutor(runnable ->
        {
            Thread thread = new Thread(runnable, "runelite-chess-audio");
            thread.setDaemon(true);
            return thread;
        });
        started = true;
        playbackFailureLogged = false;
        rememberCurrentGameState();
        controller.addListener(this);
    }

    public void stop()
    {
        ExecutorService executorToStop;
        synchronized (this)
        {
            if (!started)
            {
                return;
            }

            started = false;
            controller.removeListener(this);
            executorToStop = executor;
            executor = null;
            previousFen = null;
            previousLastMove = null;
            previousStatus = null;
        }

        if (executorToStop != null)
        {
            executorToStop.shutdownNow();
        }
    }

    @Override
    public void onGameChanged()
    {
        Sound sound = detectGameSound();
        if (sound != null)
        {
            play(sound);
        }
    }

    private synchronized Sound detectGameSound()
    {
        if (!started)
        {
            return null;
        }

        String currentFen = controller.getPositionFen();
        String currentLastMove = controller.getLastMoveUci();
        GameStatus currentStatus = controller.getGame().getStatus();
        Sound result = null;

        if (previousStatus != null && !previousStatus.isFinished() && currentStatus.isFinished())
        {
            result = Sound.GAME_END;
        }
        else if (currentLastMove != null
            && (!Objects.equals(currentFen, previousFen)
                || !Objects.equals(currentLastMove, previousLastMove)))
        {
            result = classifyMove(previousFen, currentLastMove);
        }

        previousFen = currentFen;
        previousLastMove = currentLastMove;
        previousStatus = currentStatus;
        return result;
    }

    private Sound classifyMove(String positionBeforeMove, String moveUci)
    {
        if (positionBeforeMove == null || moveUci == null)
        {
            return Sound.MOVE;
        }

        try
        {
            ChessGame previousGame = ChessGame.fromFen(positionBeforeMove);
            Move move = Move.fromUci(moveUci);
            Piece movingPiece = previousGame.getPiece(move.getFrom());
            if (movingPiece == null)
            {
                return Sound.MOVE;
            }

            int fromFile = Square.file(move.getFrom());
            int toFile = Square.file(move.getTo());
            boolean capture = previousGame.getPiece(move.getTo()) != null
                || (movingPiece.getType() == PieceType.PAWN && fromFile != toFile);
            boolean castle = movingPiece.getType() == PieceType.KING
                && Math.abs(toFile - fromFile) == 2;

            ChessGame currentGame = controller.getGame();
            if (currentGame.isInCheck(currentGame.getSideToMove()))
            {
                return Sound.CHECK;
            }
            if (castle)
            {
                return Sound.CASTLE;
            }
            if (move.getPromotion() != null)
            {
                return Sound.PROMOTION;
            }
            if (capture)
            {
                return Sound.CAPTURE;
            }
            return Sound.MOVE;
        }
        catch (IllegalArgumentException | IllegalStateException ex)
        {
            LOG.debug("Unable to classify chess move sound for {}", moveUci, ex);
            return Sound.MOVE;
        }
    }

    private synchronized void rememberCurrentGameState()
    {
        previousFen = controller.getPositionFen();
        previousLastMove = controller.getLastMoveUci();
        previousStatus = controller.getGame().getStatus();
    }

    private void play(Sound sound)
    {
        ExecutorService currentExecutor;
        synchronized (this)
        {
            if (!started || executor == null)
            {
                return;
            }
            currentExecutor = executor;
        }

        try
        {
            currentExecutor.execute(() -> playNow(sound));
        }
        catch (RejectedExecutionException ex)
        {
            LOG.debug("Chess sound task was rejected during shutdown", ex);
        }
    }

    private void playNow(Sound sound)
    {
        try
        {
            audioPlayer.play(ChessSoundService.class, sound.resourcePath, SOUND_GAIN_DB);
        }
        catch (Exception ex)
        {
            logPlaybackFailureOnce("Unable to play chess sound " + sound.resourcePath, ex);
        }
    }

    private synchronized void logPlaybackFailureOnce(String message, Exception ex)
    {
        if (playbackFailureLogged)
        {
            return;
        }

        playbackFailureLogged = true;
        LOG.debug(message, ex);
    }
}

package com.playercoder1.chess;

import java.security.SecureRandom;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.events.UserJoin;
import net.runelite.client.party.events.UserPart;

@Singleton
public final class ChessMultiplayerService
{
    public enum Mode
    {
        LOCAL,
        HOST_WAITING,
        HOST_PLAYING,
        GUEST_JOINING,
        GUEST_PLAYING
    }

    public enum MatchKind
    {
        PRIVATE,
        MATCHMADE
    }

    @FunctionalInterface
    public interface Listener
    {
        void onSessionChanged();
    }

    private static final int PROTOCOL_VERSION = 2;
    private static final String PARTY_PREFIX = "runelite-chess-";
    private static final String CODE_ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
    private static final long JOIN_RETRY_INTERVAL_MILLIS = TimeUnit.SECONDS.toMillis(2);
    private static final long OPEN_HEARTBEAT_INTERVAL_MILLIS = TimeUnit.SECONDS.toMillis(10);
    private static final long STATE_HEARTBEAT_INTERVAL_MILLIS = TimeUnit.SECONDS.toMillis(15);
    private static final int MAX_FEN_LENGTH = 128;
    private static final int MAX_NOTICE_LENGTH = 240;
    private static final int MAX_REASON_LENGTH = 160;
    private static final int MAX_UCI_LENGTH = 5;

    private final PartyService partyService;
    private final EventBus eventBus;
    private final LocalChessController controller;
    private final ChessBotService botService;
    private final SecureRandom secureRandom = new SecureRandom();
    private final List<Listener> listeners = new ArrayList<>();
    private final Map<Long, Long> lastJoinRequestByMember = new HashMap<>();

    private Mode mode = Mode.LOCAL;
    private MatchKind matchKind;
    private String invitationCode;
    private String matchToken;
    private String previousPartyPassphrase;
    private long hostMemberId;
    private long guestMemberId;
    private ChessColor hostColor = ChessColor.WHITE;
    private int initialMinutes = 10;
    private int incrementSeconds;
    private int gameNumber = 1;
    private int sequence;
    private long rematchRequestedBy;
    private long lastJoinSentMillis;
    private long lastOpenBroadcastMillis;
    private long lastStateBroadcastMillis;
    private boolean opponentConnected;
    private boolean awaitingHostMoveConfirmation;
    private boolean started;

    @Inject
    public ChessMultiplayerService(
        PartyService partyService,
        EventBus eventBus,
        LocalChessController controller,
        ChessBotService botService)
    {
        this.partyService = partyService;
        this.eventBus = eventBus;
        this.controller = controller;
        this.botService = botService;
    }

    public void start()
    {
        if (!started)
        {
            started = true;
            eventBus.register(this);
        }
    }

    public void stop()
    {
        if (!started)
        {
            return;
        }
        started = false;
        eventBus.unregister(this);
        leaveMatchInternal(true, true);
    }

    public Mode getMode()
    {
        return mode;
    }

    public boolean isOnline()
    {
        return mode != Mode.LOCAL;
    }

    public boolean isHost()
    {
        return mode == Mode.HOST_WAITING || mode == Mode.HOST_PLAYING;
    }

    public boolean isPlayingOnline()
    {
        return mode == Mode.HOST_PLAYING || mode == Mode.GUEST_PLAYING;
    }

    public boolean isMatchmade()
    {
        return isOnline() && matchKind == MatchKind.MATCHMADE;
    }

    public MatchKind getMatchKind()
    {
        return matchKind;
    }

    public String getInvitationCode()
    {
        return invitationCode;
    }

    public int getInitialMinutes()
    {
        return initialMinutes;
    }

    public int getIncrementSeconds()
    {
        return incrementSeconds;
    }

    public ChessColor getLocalColor()
    {
        if (mode == Mode.HOST_PLAYING)
        {
            return hostColor;
        }
        if (mode == Mode.GUEST_PLAYING)
        {
            return hostColor.opposite();
        }
        return null;
    }

    public boolean isOpponentConnected()
    {
        return opponentConnected;
    }

    public long getRematchRequestedBy()
    {
        return rematchRequestedBy;
    }

    public boolean isRematchRequestedByLocalPlayer()
    {
        long local = localMemberId();
        return local != 0L && rematchRequestedBy == local;
    }

    public boolean isRematchRequestedByOpponent()
    {
        return rematchRequestedBy != 0L && !isRematchRequestedByLocalPlayer();
    }

    public void addListener(Listener listener)
    {
        if (listener != null && !listeners.contains(listener))
        {
            listeners.add(listener);
        }
    }

    public void removeListener(Listener listener)
    {
        listeners.remove(listener);
    }

    public void createPrivateMatch(int minutes, int increment)
    {
        createHostedMatch(
            generateCode(),
            minutes,
            increment,
            partyService.getPartyPassphrase(),
            MatchKind.PRIVATE);
    }

    public void joinPrivateMatch(String code)
    {
        String normalized = normalizeCode(code);
        if (!isValidInvitationCode(normalized))
        {
            throw new IllegalArgumentException("Enter the eight-character invitation code.");
        }

        joinMatch(
            normalized,
            partyService.getPartyPassphrase(),
            MatchKind.PRIVATE,
            ChessTimeControl.DEFAULT_MINUTES,
            ChessTimeControl.DEFAULT_INCREMENT_SECONDS);
    }


    String generateInternalMatchCode()
    {
        return generateCode();
    }

    void startMatchmadeHost(
        String code,
        int minutes,
        int increment,
        String restorePartyPassphrase)
    {
        String normalized = normalizeCode(code);
        if (!isValidInvitationCode(normalized))
        {
            throw new IllegalArgumentException("Invalid matchmaking room token.");
        }
        createHostedMatch(
            normalized,
            minutes,
            increment,
            restorePartyPassphrase,
            MatchKind.MATCHMADE);
    }

    void startMatchmadeGuest(
        String code,
        int minutes,
        int increment,
        String restorePartyPassphrase)
    {
        String normalized = normalizeCode(code);
        if (!isValidInvitationCode(normalized))
        {
            throw new IllegalArgumentException("Invalid matchmaking room token.");
        }
        joinMatch(
            normalized,
            restorePartyPassphrase,
            MatchKind.MATCHMADE,
            minutes,
            increment);
    }

    private void createHostedMatch(
        String code,
        int minutes,
        int increment,
        String restorePartyPassphrase,
        MatchKind kind)
    {
        validateTimeControl(minutes, increment);
        botService.stopGame();
        if (isOnline())
        {
            leaveMatchInternal(true, false);
        }

        previousPartyPassphrase = restorePartyPassphrase;
        invitationCode = code;
        matchKind = kind;
        matchToken = UUID.randomUUID().toString();
        initialMinutes = minutes;
        incrementSeconds = increment;
        gameNumber = 1;
        sequence = 0;
        hostMemberId = 0L;
        guestMemberId = 0L;
        rematchRequestedBy = 0L;
        opponentConnected = false;
        awaitingHostMoveConfirmation = false;
        lastJoinSentMillis = 0L;
        lastOpenBroadcastMillis = 0L;
        lastStateBroadcastMillis = 0L;
        lastJoinRequestByMember.clear();
        hostColor = secureRandom.nextBoolean() ? ChessColor.WHITE : ChessColor.BLACK;
        mode = Mode.HOST_WAITING;
        controller.configureTimeControl(minutes, increment);
        controller.newGame();
        controller.setNotice(kind == MatchKind.MATCHMADE
            ? "Match found. Waiting for the opponent connection…"
            : "Private match created. Share code " + invitationCode + ".");
        partyService.changeParty(PARTY_PREFIX + invitationCode);
        notifyListeners();
    }

    private void joinMatch(
        String code,
        String restorePartyPassphrase,
        MatchKind kind,
        int expectedMinutes,
        int expectedIncrement)
    {
        botService.stopGame();
        if (isOnline())
        {
            leaveMatchInternal(true, false);
        }

        previousPartyPassphrase = restorePartyPassphrase;
        invitationCode = code;
        matchKind = kind;
        matchToken = null;
        hostMemberId = 0L;
        guestMemberId = 0L;
        rematchRequestedBy = 0L;
        opponentConnected = false;
        awaitingHostMoveConfirmation = false;
        lastJoinSentMillis = 0L;
        lastOpenBroadcastMillis = 0L;
        lastStateBroadcastMillis = 0L;
        lastJoinRequestByMember.clear();
        if (kind == MatchKind.MATCHMADE)
        {
            validateTimeControl(expectedMinutes, expectedIncrement);
            initialMinutes = expectedMinutes;
            incrementSeconds = expectedIncrement;
        }
        mode = Mode.GUEST_JOINING;
        controller.setNotice(kind == MatchKind.MATCHMADE
            ? "Match found. Connecting to the opponent…"
            : "Joining private match " + invitationCode + "…");
        partyService.changeParty(PARTY_PREFIX + invitationCode);
        notifyListeners();
    }

    public void leaveMatch()
    {
        leaveMatchInternal(true, false);
    }

    public boolean canSelectPiece(ChessColor pieceColor)
    {
        if (pieceColor == null || controller.getGame().getStatus().isFinished())
        {
            return false;
        }
        if (!isPlayingOnline())
        {
            return pieceColor == controller.getGame().getSideToMove()
                && botService.canHumanSelect(pieceColor);
        }
        ChessColor localColor = getLocalColor();
        return localColor != null
            && pieceColor == localColor
            && controller.getGame().getSideToMove() == localColor
            && opponentConnected
            && !awaitingHostMoveConfirmation;
    }

    public boolean canLocalPlayerAct()
    {
        if (!isPlayingOnline())
        {
            return true;
        }
        return opponentConnected && getLocalColor() != null && !awaitingHostMoveConfirmation;
    }

    public boolean playMove(Move move)
    {
        if (move == null)
        {
            return false;
        }
        if (!isPlayingOnline())
        {
            if (botService.isActive()
                && controller.getGame().getSideToMove() != botService.getHumanColor())
            {
                controller.setNotice(botService.getDifficulty().getDisplayName() + " is thinking.");
                return false;
            }
            return controller.playMove(move);
        }

        ChessColor localColor = getLocalColor();
        if (!opponentConnected || awaitingHostMoveConfirmation
            || localColor == null || controller.getGame().getSideToMove() != localColor)
        {
            controller.setNotice("Wait for your turn and for the opponent to reconnect.");
            return false;
        }

        if (isHost())
        {
            boolean played = controller.playMove(move);
            if (played)
            {
                sequence++;
                rematchRequestedBy = 0L;
                broadcastState();
            }
            return played;
        }

        ChessPartyMessage message = baseMessage(ChessPartyMessage.MOVE);
        message.targetMemberId = hostMemberId;
        message.sequence = sequence;
        message.gameNumber = gameNumber;
        message.uci = move.toUci();
        awaitingHostMoveConfirmation = true;
        partyService.send(message);
        controller.setNotice("Move sent — waiting for host confirmation.");
        notifyListeners();
        return true;
    }

    public void offerAcceptOrCancelDraw()
    {
        if (!isPlayingOnline())
        {
            if (botService.isActive())
            {
                controller.setNotice("Computer opponents do not accept draw offers.");
                return;
            }
            controller.offerAcceptOrCancelDraw();
            return;
        }
        if (!canLocalPlayerAct() || controller.getGame().getStatus().isFinished())
        {
            return;
        }

        ChessColor actor = getLocalColor();
        if (isHost())
        {
            controller.handleDrawAction(actor);
            sequence++;
            broadcastState();
        }
        else
        {
            ChessPartyMessage message = baseMessage(ChessPartyMessage.DRAW);
            message.targetMemberId = hostMemberId;
            message.sequence = sequence;
            message.gameNumber = gameNumber;
            partyService.send(message);
        }
    }

    public void resign()
    {
        if (!isPlayingOnline())
        {
            if (botService.isActive())
            {
                controller.resign(botService.getHumanColor());
            }
            else
            {
                controller.resignCurrentPlayer();
            }
            return;
        }
        if (!canLocalPlayerAct() || controller.getGame().getStatus().isFinished())
        {
            return;
        }

        if (isHost())
        {
            controller.resign(getLocalColor());
            sequence++;
            broadcastState();
        }
        else
        {
            ChessPartyMessage message = baseMessage(ChessPartyMessage.RESIGN);
            message.targetMemberId = hostMemberId;
            message.sequence = sequence;
            message.gameNumber = gameNumber;
            partyService.send(message);
        }
    }

    public void requestOrAcceptRematch()
    {
        if (!isPlayingOnline() || !controller.getGame().getStatus().isFinished() || !opponentConnected)
        {
            return;
        }

        long local = localMemberId();
        if (local == 0L || rematchRequestedBy == local)
        {
            return;
        }

        if (isHost())
        {
            if (rematchRequestedBy == guestMemberId)
            {
                startRematch();
            }
            else
            {
                rematchRequestedBy = hostMemberId;
                broadcastState();
            }
            return;
        }

        ChessPartyMessage message = baseMessage(
            rematchRequestedBy == hostMemberId
                ? ChessPartyMessage.REMATCH_ACCEPT
                : ChessPartyMessage.REMATCH_REQUEST);
        message.targetMemberId = hostMemberId;
        message.gameNumber = gameNumber;
        message.sequence = sequence;
        partyService.send(message);
        if (rematchRequestedBy == 0L)
        {
            rematchRequestedBy = guestMemberId;
            notifyListeners();
        }
    }

    public void startLocalGame(int minutes, int increment)
    {
        validateTimeControl(minutes, increment);
        botService.stopGame();
        if (isOnline())
        {
            leaveMatchInternal(true, false);
        }
        controller.configureTimeControl(minutes, increment);
        controller.newGame();
    }

    public void startBotGame(
        BotDifficulty difficulty,
        ChessColor humanColor,
        int minutes,
        int increment)
    {
        validateTimeControl(minutes, increment);
        if (isOnline())
        {
            leaveMatchInternal(true, false);
        }
        botService.startGame(difficulty, humanColor, minutes, increment);
        notifyListeners();
    }

    public void tick()
    {
        long now = System.currentTimeMillis();
        switch (mode)
        {
            case LOCAL:
                controller.tick();
                break;
            case HOST_WAITING:
                if (now - lastOpenBroadcastMillis >= OPEN_HEARTBEAT_INTERVAL_MILLIS)
                {
                    sendOpen(0L);
                }
                break;
            case HOST_PLAYING:
                GameStatus before = controller.getGame().getStatus();
                controller.tick();
                if (before != controller.getGame().getStatus()
                    || now - lastStateBroadcastMillis >= STATE_HEARTBEAT_INTERVAL_MILLIS)
                {
                    broadcastState();
                }
                break;
            case GUEST_JOINING:
                sendJoinRequest();
                break;
            case GUEST_PLAYING:
                controller.tickDisplayOnly();
                break;
            default:
                break;
        }
    }

    @Subscribe
    public void onUserJoin(UserJoin event)
    {
        runOnSwingThread(() -> handleUserJoin(event));
    }

    @Subscribe
    public void onUserPart(UserPart event)
    {
        runOnSwingThread(() -> handleUserPart(event));
    }

    @Subscribe
    public void onChessPartyMessage(ChessPartyMessage message)
    {
        runOnSwingThread(() -> handlePartyMessage(message));
    }

    private void handleUserJoin(UserJoin event)
    {
        if (!isOnline() || event == null || event.getPartyId() != partyService.getPartyId())
        {
            return;
        }

        long local = localMemberId();
        if (isHost())
        {
            if (hostMemberId == 0L && local != 0L)
            {
                hostMemberId = local;
            }
            if (event.getMemberId() == guestMemberId && guestMemberId != 0L)
            {
                opponentConnected = true;
                sendAccept(guestMemberId);
                broadcastState();
            }
            else if (mode == Mode.HOST_WAITING)
            {
                sendOpen(event.getMemberId());
            }
        }
        else if (mode == Mode.GUEST_JOINING)
        {
            sendJoinRequest();
        }
        else if (mode == Mode.GUEST_PLAYING && event.getMemberId() == hostMemberId)
        {
            opponentConnected = true;
            sendSyncRequest();
            notifyListeners();
        }
    }

    private void handleUserPart(UserPart event)
    {
        if (!isOnline() || event == null)
        {
            return;
        }

        long opponent = isHost() ? guestMemberId : hostMemberId;
        if (opponent != 0L && event.getMemberId() == opponent)
        {
            opponentConnected = false;
            controller.setNotice("Opponent disconnected. Their seat remains locked while reconnecting.");
            notifyListeners();
        }
    }

    private void handlePartyMessage(ChessPartyMessage message)
    {
        if (!isOnline() || message == null || message.kind == null
            || message.protocolVersion != PROTOCOL_VERSION)
        {
            return;
        }

        long local = localMemberId();
        if (local != 0L && message.getMemberId() == local)
        {
            return;
        }
        if (message.targetMemberId != 0L && message.targetMemberId != local)
        {
            return;
        }

        switch (message.kind)
        {
            case ChessPartyMessage.OPEN:
                handleOpen(message);
                break;
            case ChessPartyMessage.JOIN:
                handleJoinRequest(message);
                break;
            case ChessPartyMessage.ACCEPT:
                handleAccept(message);
                break;
            case ChessPartyMessage.REJECT:
                handleReject(message);
                break;
            case ChessPartyMessage.MOVE:
                handleMoveRequest(message);
                break;
            case ChessPartyMessage.STATE:
                handleState(message);
                break;
            case ChessPartyMessage.DRAW:
                handleDrawRequest(message);
                break;
            case ChessPartyMessage.RESIGN:
                handleResignRequest(message);
                break;
            case ChessPartyMessage.REMATCH_REQUEST:
                handleRematchRequest(message);
                break;
            case ChessPartyMessage.REMATCH_ACCEPT:
                handleRematchAccept(message);
                break;
            case ChessPartyMessage.SYNC_REQUEST:
                if (isHost() && isAcceptedGuest(message) && sameMatch(message))
                {
                    opponentConnected = true;
                    broadcastState();
                }
                break;
            case ChessPartyMessage.LEAVE:
                if (sameMatch(message) && isOpponent(message.getMemberId()))
                {
                    opponentConnected = false;
                    awaitingHostMoveConfirmation = false;
                    controller.setNotice(isMatchmade()
                        ? "Opponent left the quick match."
                        : "Opponent closed the private match.");
                    notifyListeners();
                }
                break;
            default:
                break;
        }
    }

    private void handleOpen(ChessPartyMessage message)
    {
        if (mode != Mode.GUEST_JOINING || message.getMemberId() == 0L
            || !matchesInvitation(message) || !isSupportedTimeControl(message.initialMinutes, message.incrementSeconds)
            || (isMatchmade()
                && (message.initialMinutes != initialMinutes
                    || message.incrementSeconds != incrementSeconds)))
        {
            return;
        }

        long announcedHost = message.hostMemberId == 0L
            ? message.getMemberId()
            : message.hostMemberId;
        if (announcedHost != message.getMemberId()
            || (hostMemberId != 0L && hostMemberId != announcedHost))
        {
            return;
        }

        hostMemberId = announcedHost;
        initialMinutes = message.initialMinutes;
        incrementSeconds = message.incrementSeconds;
        sendJoinRequest();
    }

    private void handleJoinRequest(ChessPartyMessage message)
    {
        if (!isHost() || message.getMemberId() == 0L || !matchesInvitation(message))
        {
            return;
        }

        long now = System.currentTimeMillis();
        long last = lastJoinRequestByMember.getOrDefault(message.getMemberId(), 0L);
        if (now - last < JOIN_RETRY_INTERVAL_MILLIS)
        {
            return;
        }
        lastJoinRequestByMember.put(message.getMemberId(), now);

        if (guestMemberId == 0L)
        {
            guestMemberId = message.getMemberId();
            opponentConnected = true;
            mode = Mode.HOST_PLAYING;
            controller.configureTimeControl(initialMinutes, incrementSeconds);
            controller.newGame();
            controller.setNotice((isMatchmade() ? "Quick match connected. " : "Private match connected. ")
                + controller.describePosition());
            sendAccept(guestMemberId);
            broadcastState();
            notifyListeners();
        }
        else if (guestMemberId == message.getMemberId())
        {
            opponentConnected = true;
            sendAccept(guestMemberId);
            broadcastState();
            notifyListeners();
        }
        else
        {
            ChessPartyMessage rejection = baseMessage(ChessPartyMessage.REJECT);
            rejection.targetMemberId = message.getMemberId();
            rejection.reason = "This one-use invitation has already been consumed by two players.";
            partyService.send(rejection);
        }
    }

    private void handleAccept(ChessPartyMessage message)
    {
        if ((mode != Mode.GUEST_JOINING && mode != Mode.GUEST_PLAYING)
            || message.getMemberId() == 0L
            || !matchesInvitation(message)
            || !isValidMatchToken(message.matchToken)
            || !isSupportedTimeControl(message.initialMinutes, message.incrementSeconds)
            || (isMatchmade()
                && (message.initialMinutes != initialMinutes
                    || message.incrementSeconds != incrementSeconds))
            || message.gameNumber < 1
            || message.sequence < 0)
        {
            return;
        }

        long local = localMemberId();
        long announcedHost = message.hostMemberId == 0L
            ? message.getMemberId()
            : message.hostMemberId;
        if (local == 0L || message.guestMemberId != local
            || announcedHost != message.getMemberId()
            || (hostMemberId != 0L && hostMemberId != announcedHost))
        {
            return;
        }
        if (mode == Mode.GUEST_PLAYING
            && (!sameMatch(message)
                || message.gameNumber < gameNumber
                || (message.gameNumber == gameNumber && message.sequence < sequence)))
        {
            return;
        }

        ChessColor acceptedHostColor;
        try
        {
            acceptedHostColor = parseOptionalColor(message.hostColor);
        }
        catch (IllegalArgumentException ex)
        {
            return;
        }
        if (acceptedHostColor == null)
        {
            return;
        }

        boolean firstAcceptance = mode == Mode.GUEST_JOINING;
        hostMemberId = announcedHost;
        guestMemberId = message.guestMemberId;
        matchToken = message.matchToken.trim();
        invitationCode = normalizeCode(message.invitationCode == null ? invitationCode : message.invitationCode);
        hostColor = acceptedHostColor;
        initialMinutes = message.initialMinutes;
        incrementSeconds = message.incrementSeconds;
        gameNumber = message.gameNumber;
        sequence = message.sequence;
        opponentConnected = true;
        awaitingHostMoveConfirmation = false;
        mode = Mode.GUEST_PLAYING;

        if (firstAcceptance)
        {
            controller.configureTimeControl(initialMinutes, incrementSeconds);
            controller.newGame();
            controller.setNotice("Connected. You are " + getLocalColor().displayName() + ".");
            sendSyncRequest();
        }
        notifyListeners();
    }

    private void handleReject(ChessPartyMessage message)
    {
        if (mode != Mode.GUEST_JOINING || message.getMemberId() == 0L
            || !matchesInvitation(message))
        {
            return;
        }

        long announcedHost = message.hostMemberId == 0L
            ? message.getMemberId()
            : message.hostMemberId;
        if (announcedHost != message.getMemberId()
            || (hostMemberId != 0L && hostMemberId != announcedHost))
        {
            return;
        }

        hostMemberId = announcedHost;
        String reason = sanitizedText(
            message.reason,
            MAX_REASON_LENGTH,
            isMatchmade()
                ? "The matchmaking session is no longer available."
                : "The invitation is no longer available.");
        leaveMatchInternal(true, false);
        controller.setNotice(reason);
    }

    private void handleMoveRequest(ChessPartyMessage message)
    {
        if (!isHost() || !isAcceptedGuest(message) || !sameMatch(message))
        {
            return;
        }
        if (message.gameNumber != gameNumber || message.sequence != sequence)
        {
            broadcastState();
            return;
        }
        if (controller.getGame().getSideToMove() != hostColor.opposite())
        {
            broadcastState();
            return;
        }

        try
        {
            Move move = Move.fromUci(message.uci);
            if (controller.playMove(move))
            {
                sequence++;
                rematchRequestedBy = 0L;
            }
        }
        catch (IllegalArgumentException ignored)
        {

        }
        broadcastState();
    }

    private void handleState(ChessPartyMessage message)
    {
        long local = localMemberId();
        if (mode != Mode.GUEST_PLAYING || local == 0L
            || message.getMemberId() != hostMemberId || !sameMatch(message)
            || message.hostMemberId != hostMemberId || message.guestMemberId != local
            || !isSupportedTimeControl(message.initialMinutes, message.incrementSeconds)
            || message.gameNumber < 1 || message.sequence < 0
            || message.whiteMillis < 0L || message.blackMillis < 0L
            || message.positionFen == null || message.positionFen.trim().isEmpty()
            || message.positionFen.length() > MAX_FEN_LENGTH
            || (message.lastMoveUci != null && message.lastMoveUci.length() > MAX_UCI_LENGTH)
            || !isKnownMemberOrNobody(message.rematchRequestedBy))
        {
            return;
        }
        if (message.gameNumber < gameNumber
            || (message.gameNumber == gameNumber && message.sequence < sequence))
        {
            return;
        }

        try
        {
            GameStatus status = parseRequiredStatus(message.gameStatus);
            ChessColor active = parseOptionalColor(message.activeColor);
            ChessColor offeredBy = parseOptionalColor(message.drawOfferedBy);
            ChessColor stateHostColor = parseOptionalColor(message.hostColor);
            if ((message.clockRunning && active == null) || stateHostColor == null)
            {
                throw new IllegalArgumentException("Incomplete clock or color state");
            }
            controller.restoreNetworkState(
                message.initialMinutes,
                message.incrementSeconds,
                message.positionFen,
                message.lastMoveUci,
                message.whiteMillis,
                message.blackMillis,
                active,
                message.clockRunning,
                offeredBy,
                status,
                sanitizedText(message.notice, MAX_NOTICE_LENGTH, null));
            initialMinutes = message.initialMinutes;
            incrementSeconds = message.incrementSeconds;
            gameNumber = message.gameNumber;
            sequence = message.sequence;
            rematchRequestedBy = message.rematchRequestedBy;
            hostColor = stateHostColor;
            opponentConnected = true;
            awaitingHostMoveConfirmation = false;
            notifyListeners();
        }
        catch (IllegalArgumentException ex)
        {
            controller.setNotice("Could not apply the host state. Requesting another sync.");
            sendSyncRequest();
        }
    }

    private void handleDrawRequest(ChessPartyMessage message)
    {
        if (!isHost() || !isAcceptedGuest(message) || !sameMatch(message)
            || message.gameNumber != gameNumber || message.sequence != sequence
            || controller.getGame().getStatus().isFinished())
        {
            broadcastState();
            return;
        }
        controller.handleDrawAction(hostColor.opposite());
        sequence++;
        broadcastState();
    }

    private void handleResignRequest(ChessPartyMessage message)
    {
        if (!isHost() || !isAcceptedGuest(message) || !sameMatch(message)
            || message.gameNumber != gameNumber || message.sequence != sequence
            || controller.getGame().getStatus().isFinished())
        {
            broadcastState();
            return;
        }
        controller.resign(hostColor.opposite());
        sequence++;
        broadcastState();
    }

    private void handleRematchRequest(ChessPartyMessage message)
    {
        if (!isHost() || !isAcceptedGuest(message) || !sameMatch(message)
            || message.gameNumber != gameNumber || message.sequence != sequence
            || !controller.getGame().getStatus().isFinished())
        {
            return;
        }
        if (rematchRequestedBy == hostMemberId)
        {
            startRematch();
        }
        else
        {
            rematchRequestedBy = guestMemberId;
            broadcastState();
        }
    }

    private void handleRematchAccept(ChessPartyMessage message)
    {
        if (isHost() && isAcceptedGuest(message) && sameMatch(message)
            && message.gameNumber == gameNumber && message.sequence == sequence
            && controller.getGame().getStatus().isFinished()
            && rematchRequestedBy == hostMemberId)
        {
            startRematch();
        }
    }

    private void startRematch()
    {
        gameNumber++;
        sequence = 0;
        rematchRequestedBy = 0L;
        hostColor = hostColor.opposite();
        controller.configureTimeControl(initialMinutes, incrementSeconds);
        controller.newGame();
        controller.setNotice("Rematch started. Colors were swapped.");
        broadcastState();
        notifyListeners();
    }

    private void sendOpen(long targetMemberId)
    {
        if (!isHost() || invitationCode == null)
        {
            return;
        }
        if (hostMemberId == 0L)
        {
            hostMemberId = localMemberId();
        }
        if (hostMemberId == 0L)
        {
            return;
        }

        ChessPartyMessage message = baseMessage(ChessPartyMessage.OPEN);
        message.matchToken = null;
        message.targetMemberId = targetMemberId;
        message.invitationCode = invitationCode;
        message.hostMemberId = hostMemberId;
        message.initialMinutes = initialMinutes;
        message.incrementSeconds = incrementSeconds;
        partyService.send(message);
        lastOpenBroadcastMillis = System.currentTimeMillis();
    }

    private void sendJoinRequest()
    {
        if (mode != Mode.GUEST_JOINING)
        {
            return;
        }
        long local = localMemberId();
        long now = System.currentTimeMillis();
        if (local == 0L || now - lastJoinSentMillis < JOIN_RETRY_INTERVAL_MILLIS)
        {
            return;
        }

        ChessPartyMessage message = baseMessage(ChessPartyMessage.JOIN);
        message.targetMemberId = hostMemberId;
        message.invitationCode = invitationCode;
        partyService.send(message);
        lastJoinSentMillis = now;
    }

    private void sendAccept(long targetMemberId)
    {
        ChessPartyMessage message = baseMessage(ChessPartyMessage.ACCEPT);
        message.targetMemberId = targetMemberId;
        message.invitationCode = invitationCode;
        message.matchToken = matchToken;
        message.hostMemberId = hostMemberId;
        message.guestMemberId = guestMemberId;
        message.initialMinutes = initialMinutes;
        message.incrementSeconds = incrementSeconds;
        message.gameNumber = gameNumber;
        message.sequence = sequence;
        message.hostColor = hostColor.name();
        partyService.send(message);
    }

    private void sendSyncRequest()
    {
        if (mode != Mode.GUEST_PLAYING || hostMemberId == 0L)
        {
            return;
        }
        ChessPartyMessage message = baseMessage(ChessPartyMessage.SYNC_REQUEST);
        message.targetMemberId = hostMemberId;
        message.gameNumber = gameNumber;
        message.sequence = sequence;
        partyService.send(message);
    }

    private void broadcastState()
    {
        if (!isHost() || guestMemberId == 0L || matchToken == null)
        {
            return;
        }

        ChessPartyMessage message = baseMessage(ChessPartyMessage.STATE);
        message.targetMemberId = guestMemberId;
        message.hostMemberId = hostMemberId;
        message.guestMemberId = guestMemberId;
        message.initialMinutes = initialMinutes;
        message.incrementSeconds = incrementSeconds;
        message.gameNumber = gameNumber;
        message.sequence = sequence;
        message.hostColor = hostColor.name();
        message.positionFen = controller.getPositionFen();
        message.lastMoveUci = controller.getLastMoveUci();
        message.whiteMillis = controller.getClock().getRemainingMillis(ChessColor.WHITE);
        message.blackMillis = controller.getClock().getRemainingMillis(ChessColor.BLACK);
        ChessColor active = controller.getClock().getActiveColor();
        message.activeColor = active == null ? null : active.name();
        message.clockRunning = controller.getClock().isRunning();
        message.gameStatus = controller.getGame().getStatus().name();
        ChessColor offeredBy = controller.getDrawOfferedBy();
        message.drawOfferedBy = offeredBy == null ? null : offeredBy.name();
        message.rematchRequestedBy = rematchRequestedBy;
        message.notice = sanitizedText(controller.getNotice(), MAX_NOTICE_LENGTH, "");
        partyService.send(message);
        lastStateBroadcastMillis = System.currentTimeMillis();
    }

    private ChessPartyMessage baseMessage(String kind)
    {
        ChessPartyMessage message = new ChessPartyMessage();
        message.protocolVersion = PROTOCOL_VERSION;
        message.kind = kind;
        message.invitationCode = invitationCode;
        message.matchToken = matchToken;
        message.hostMemberId = hostMemberId;
        message.guestMemberId = guestMemberId;
        return message;
    }

    private boolean isAcceptedGuest(ChessPartyMessage message)
    {
        return message != null && guestMemberId != 0L && message.getMemberId() == guestMemberId;
    }

    private boolean isOpponent(long memberId)
    {
        return memberId != 0L && memberId == (isHost() ? guestMemberId : hostMemberId);
    }

    private boolean sameMatch(ChessPartyMessage message)
    {
        return message != null
            && matchToken != null
            && matchToken.equals(message.matchToken);
    }

    private boolean matchesInvitation(ChessPartyMessage message)
    {
        return message != null
            && invitationCode != null
            && invitationCode.equals(normalizeCode(message.invitationCode));
    }

    private static boolean isSupportedTimeControl(int minutes, int increment)
    {
        return ChessTimeControl.isSupported(minutes, increment);
    }

    private long localMemberId()
    {
        PartyMember member = partyService.getLocalMember();
        return member == null ? 0L : member.getMemberId();
    }

    private void leaveMatchInternal(boolean restorePreviousParty, boolean shuttingDown)
    {
        if (isOnline())
        {
            long local = localMemberId();
            if (local != 0L && matchToken != null)
            {
                ChessPartyMessage leave = baseMessage(ChessPartyMessage.LEAVE);
                leave.targetMemberId = isHost() ? guestMemberId : hostMemberId;
                try
                {
                    partyService.send(leave);
                }
                catch (RuntimeException ignored)
                {

                }
            }
        }

        String restore = restorePreviousParty ? previousPartyPassphrase : null;
        mode = Mode.LOCAL;
        matchKind = null;
        invitationCode = null;
        matchToken = null;
        hostMemberId = 0L;
        guestMemberId = 0L;
        rematchRequestedBy = 0L;
        opponentConnected = false;
        awaitingHostMoveConfirmation = false;
        sequence = 0;
        gameNumber = 1;
        lastJoinSentMillis = 0L;
        lastOpenBroadcastMillis = 0L;
        lastStateBroadcastMillis = 0L;
        lastJoinRequestByMember.clear();
        previousPartyPassphrase = null;

        if (partyService.isInParty() && (restorePreviousParty || shuttingDown))
        {
            partyService.changeParty(restore);
        }
        if (!shuttingDown)
        {
            controller.setNotice("Returned to local chess.");
            notifyListeners();
        }
    }

    private void notifyListeners()
    {
        for (Listener listener : new ArrayList<>(listeners))
        {
            listener.onSessionChanged();
        }
    }

    private void runOnSwingThread(Runnable runnable)
    {
        if (SwingUtilities.isEventDispatchThread())
        {
            runnable.run();
        }
        else
        {
            SwingUtilities.invokeLater(runnable);
        }
    }

    private String generateCode()
    {
        StringBuilder result = new StringBuilder(8);
        for (int i = 0; i < 8; i++)
        {
            result.append(CODE_ALPHABET.charAt(secureRandom.nextInt(CODE_ALPHABET.length())));
        }
        return result.toString();
    }

    public static String formatCode(String code)
    {
        String normalized = normalizeCode(code);
        if (normalized.length() <= 4)
        {
            return normalized;
        }
        return normalized.substring(0, 4) + "-" + normalized.substring(4);
    }

    private static String normalizeCode(String code)
    {
        if (code == null)
        {
            return "";
        }

        StringBuilder normalized = new StringBuilder(8);
        for (int i = 0; i < code.length(); i++)
        {
            char value = Character.toUpperCase(code.charAt(i));
            if ((value >= 'A' && value <= 'Z') || (value >= '0' && value <= '9'))
            {
                normalized.append(value);
            }
        }
        return normalized.toString();
    }

    private static boolean isValidInvitationCode(String code)
    {
        if (code == null || code.length() != 8)
        {
            return false;
        }
        for (int i = 0; i < code.length(); i++)
        {
            if (CODE_ALPHABET.indexOf(code.charAt(i)) < 0)
            {
                return false;
            }
        }
        return true;
    }

    private static void validateTimeControl(int minutes, int increment)
    {
        ChessTimeControl.validate(minutes, increment);
    }

    private boolean isKnownMemberOrNobody(long memberId)
    {
        return memberId == 0L || memberId == hostMemberId || memberId == guestMemberId;
    }

    private static boolean isValidMatchToken(String token)
    {
        if (token == null || token.length() > 36)
        {
            return false;
        }
        try
        {
            return UUID.fromString(token).toString().equals(token);
        }
        catch (IllegalArgumentException ex)
        {
            return false;
        }
    }

    private static String sanitizedText(String text, int maxLength, String fallback)
    {
        if (text == null || text.trim().isEmpty())
        {
            return fallback;
        }
        String trimmed = text.trim();
        return trimmed.length() <= maxLength ? trimmed : trimmed.substring(0, maxLength);
    }

    private static ChessColor parseOptionalColor(String value)
    {
        if (value == null || value.trim().isEmpty())
        {
            return null;
        }
        return ChessColor.valueOf(value.trim());
    }

    private static GameStatus parseRequiredStatus(String value)
    {
        if (value == null || value.trim().isEmpty())
        {
            throw new IllegalArgumentException("Missing game status");
        }
        return GameStatus.valueOf(value.trim());
    }
}

package com.playercoder1;

import com.playercoder1.chess.ChessBotService;
import com.playercoder1.chess.ChessColor;
import com.playercoder1.chess.ChessLobbyMessage;
import com.playercoder1.chess.ChessMatchmakingService;
import com.playercoder1.chess.ChessMultiplayerService;
import com.playercoder1.chess.ChessPartyMessage;
import com.playercoder1.chess.ChessSoundService;
import com.playercoder1.ui.ChessBoardOverlay;
import com.playercoder1.ui.ChessClubOverlay;
import com.playercoder1.ui.ChessLobbyOverlay;
import com.playercoder1.ui.ChessMatchControlsOverlay;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.Point;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.input.MouseManager;
import net.runelite.client.party.WSClient;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;

@PluginDescriptor(
        name = "Chess",
        description = "Play local, computer, or online chess from the sidebar or Varrock Chess Club",
        tags = {"chess", "board", "computer", "sidebar", "overlay", "multiplayer", "matchmaking", "party", "varrock"}
)
public class ChessPlugin extends Plugin implements ChessMultiplayerService.Listener
{

    private static final int VARROCK_CHESS_TABLE_OBJECT_ID = 17451;
    private static final String PLAY_CHESS = "Play";
    private static final String FIND_OPPONENT = "Find opponent";
    private static final String PRIVATE_MATCH = "Private match";

    @Inject
    private Client client;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private ChessPanel panel;

    @Inject
    private ChessBoardOverlay boardOverlay;

    @Inject
    private ChessLobbyOverlay lobbyOverlay;

    @Inject
    private ChessClubOverlay clubOverlay;

    @Inject
    private ChessMatchControlsOverlay matchControlsOverlay;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private MouseManager mouseManager;

    @Inject
    private WSClient wsClient;

    @Inject
    private ChessMultiplayerService multiplayerService;

    @Inject
    private ChessMatchmakingService matchmakingService;

    @Inject
    private ChessBotService botService;

    @Inject
    private ChessSoundService soundService;

    private NavigationButton navigationButton;
    private ChessColor lastAutoOrientedColor;
    private boolean pendingTableMatch;

    @Override
    protected void startUp()
    {
        wsClient.registerMessage(ChessPartyMessage.class);
        wsClient.registerMessage(ChessLobbyMessage.class);
        botService.start();
        multiplayerService.start();
        multiplayerService.addListener(this);
        matchmakingService.start();
        soundService.start();

        overlayManager.add(boardOverlay);
        overlayManager.add(clubOverlay);
        overlayManager.add(lobbyOverlay);
        overlayManager.add(matchControlsOverlay);
        mouseManager.registerMouseListener(boardOverlay);
        mouseManager.registerMouseListener(clubOverlay);
        mouseManager.registerMouseListener(lobbyOverlay);
        mouseManager.registerMouseListener(matchControlsOverlay);

        BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/chess_icon.png");
        navigationButton = NavigationButton.builder()
                .tooltip("Chess")
                .icon(icon)
                .priority(7)
                .panel(panel)
                .build();

        SwingUtilities.invokeLater(() ->
        {
            panel.start();
            clientToolbar.addNavigation(navigationButton);
        });
    }

    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded event)
    {
        if (event.getType() != MenuAction.EXAMINE_OBJECT.getId()
                || event.getIdentifier() != VARROCK_CHESS_TABLE_OBJECT_ID)
        {
            return;
        }


        client.createMenuEntry(-1)
                .setOption(PRIVATE_MATCH)
                .setTarget(event.getTarget())
                .setType(MenuAction.RUNELITE)
                .setIdentifier(event.getIdentifier())
                .setParam0(event.getActionParam0())
                .setParam1(event.getActionParam1())
                .setWorldViewId(event.getMenuEntry().getWorldViewId())
                .onClick(entry -> openPrivateMatchFromTable());

        client.createMenuEntry(-1)
                .setOption(FIND_OPPONENT)
                .setTarget(event.getTarget())
                .setType(MenuAction.RUNELITE)
                .setIdentifier(event.getIdentifier())
                .setParam0(event.getActionParam0())
                .setParam1(event.getActionParam1())
                .setWorldViewId(event.getMenuEntry().getWorldViewId())
                .onClick(entry -> openLobbyFromTable());

        client.createMenuEntry(-1)
                .setOption(PLAY_CHESS)
                .setTarget(event.getTarget())
                .setType(MenuAction.RUNELITE)
                .setIdentifier(event.getIdentifier())
                .setParam0(event.getActionParam0())
                .setParam1(event.getActionParam1())
                .setWorldViewId(event.getMenuEntry().getWorldViewId())
                .onClick(entry -> openChessFromTable());
    }

    private void openChessFromTable()
    {
        if (multiplayerService.isPlayingOnline())
        {
            SwingUtilities.invokeLater(() ->
            {
                boardOverlay.setVisible(true);
                boardOverlay.fitToCanvasIfNeeded();
            });
            onSessionChanged();
            return;
        }

        if (matchmakingService.isLobbyOpen())
        {
            matchmakingService.closeLobby();
            lobbyOverlay.close();
        }

        Point mouse = client.getMouseCanvasPosition();
        int x = mouse == null ? 30 : mouse.getX();
        int y = mouse == null ? 100 : mouse.getY();
        clubOverlay.openAt(x, y);
    }

    private void openPrivateMatchFromTable()
    {
        if (multiplayerService.isPlayingOnline())
        {
            SwingUtilities.invokeLater(() ->
            {
                boardOverlay.setVisible(true);
                boardOverlay.fitToCanvasIfNeeded();
            });
            onSessionChanged();
            return;
        }

        if (matchmakingService.isLobbyOpen())
        {
            matchmakingService.closeLobby();
            lobbyOverlay.close();
        }

        Point mouse = client.getMouseCanvasPosition();
        int x = mouse == null ? 30 : mouse.getX();
        int y = mouse == null ? 100 : mouse.getY();
        clubOverlay.openPrivateAt(x, y);
    }

    private void openLobbyFromTable()
    {
        clubOverlay.close();
        try
        {
            matchmakingService.openLobby();
            Point mouse = client.getMouseCanvasPosition();
            int x = mouse == null ? 30 : mouse.getX();
            int y = mouse == null ? 100 : mouse.getY();
            lobbyOverlay.openAt(x, y);
        }
        catch (IllegalStateException ex)
        {

            if (multiplayerService.isPlayingOnline())
            {
                onSessionChanged();
            }
            else
            {
                SwingUtilities.invokeLater(this::openPanel);
            }
        }
    }

    @Override
    public void onSessionChanged()
    {
        Runnable sync = () ->
        {
            if (multiplayerService.isOnline() && !multiplayerService.isPlayingOnline())
            {
                pendingTableMatch |= lobbyOverlay.isOpen() || clubOverlay.isOpen();
            }
            if (multiplayerService.isPlayingOnline())
            {


                boolean openedFromTable = pendingTableMatch || lobbyOverlay.isOpen() || clubOverlay.isOpen();
                pendingTableMatch = false;
                lobbyOverlay.close();
                clubOverlay.close();
                if (openedFromTable)
                {
                    boardOverlay.setVisible(true);
                    boardOverlay.fitToCanvasIfNeeded();
                }
                matchControlsOverlay.showForMatch();

                ChessColor localColor = multiplayerService.getLocalColor();
                if (localColor != null && localColor != lastAutoOrientedColor)
                {
                    boardOverlay.setFlipped(localColor == ChessColor.BLACK);
                    lastAutoOrientedColor = localColor;
                }
                return;
            }

            matchControlsOverlay.setVisible(false);
            if (!multiplayerService.isOnline())
            {
                lastAutoOrientedColor = null;
                pendingTableMatch = false;
            }
        };

        if (SwingUtilities.isEventDispatchThread())
        {
            sync.run();
        }
        else
        {
            SwingUtilities.invokeLater(sync);
        }
    }

    private void openPanel()
    {
        if (navigationButton != null)
        {
            clientToolbar.openPanel(navigationButton);
        }
    }

    @Override
    protected void shutDown()
    {
        soundService.stop();
        boardOverlay.setVisible(false);
        lobbyOverlay.close();
        clubOverlay.close();
        matchControlsOverlay.setVisible(false);
        matchmakingService.stop();
        botService.stop();

        mouseManager.unregisterMouseListener(matchControlsOverlay);
        mouseManager.unregisterMouseListener(lobbyOverlay);
        mouseManager.unregisterMouseListener(clubOverlay);
        mouseManager.unregisterMouseListener(boardOverlay);
        overlayManager.remove(matchControlsOverlay);
        overlayManager.remove(lobbyOverlay);
        overlayManager.remove(clubOverlay);
        overlayManager.remove(boardOverlay);

        multiplayerService.removeListener(this);
        multiplayerService.stop();
        wsClient.unregisterMessage(ChessLobbyMessage.class);
        wsClient.unregisterMessage(ChessPartyMessage.class);

        SwingUtilities.invokeLater(() ->
        {
            panel.stop();
            if (navigationButton != null)
            {
                clientToolbar.removeNavigation(navigationButton);
                navigationButton = null;
            }
        });
    }
}

package com.playercoder1.ui;

import com.playercoder1.chess.ChessMatchmakingService;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.input.MouseListener;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;


@Singleton
public final class ChessLobbyOverlay extends Overlay implements MouseListener
{
    private static final int WIDTH = 252;
    private static final int PADDING = 10;
    private static final int HEADER_HEIGHT = 50;
    private static final int ROW_HEIGHT = 27;
    private static final int ROW_GAP = 3;
    private static final int FOOTER_HEIGHT = 58;

    private static final Color BACKGROUND = new Color(22, 22, 22, 242);
    private static final Color HEADER = new Color(32, 32, 32, 248);
    private static final Color BORDER = new Color(190, 145, 68);
    private static final Color ROW = new Color(48, 48, 48, 245);
    private static final Color ROW_HOVER = new Color(64, 64, 64, 248);
    private static final Color ROW_SELECTED = new Color(92, 70, 37, 248);
    private static final Color TEXT = new Color(238, 238, 238);
    private static final Color MUTED = new Color(183, 183, 183);
    private static final Color ACCENT = new Color(221, 172, 78);
    private static final Color SUCCESS = new Color(105, 177, 101);
    private static final Color DANGER = new Color(202, 88, 79);

    private final Client client;
    private final ClientThread clientThread;
    private final ChessMatchmakingService matchmaking;
    private final List<QueueHitbox> queueHitboxes = new ArrayList<>();
    private final Rectangle closeBounds = new Rectangle();

    private boolean open;
    private boolean consumingMouseSequence;
    private int hoveredQueue = -1;

    @Inject
    public ChessLobbyOverlay(Client client, ClientThread clientThread, ChessMatchmakingService matchmaking)
    {
        this.client = client;
        this.clientThread = clientThread;
        this.matchmaking = matchmaking;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(PRIORITY_HIGH);
        setMovable(true);
        setResizable(false);
        setPreferredLocation(new Point(30, 80));
    }

    public void openAt(int canvasX, int canvasY)
    {
        int height = overlayHeight();
        int maxX = Math.max(10, client.getCanvasWidth() - WIDTH - 10);
        int maxY = Math.max(10, client.getCanvasHeight() - height - 10);
        int x = clamp(canvasX + 16, 10, maxX);
        int y = clamp(canvasY - 80, 10, maxY);
        setPreferredLocation(new Point(x, y));
        open = true;
        revalidate();
    }

    public void close()
    {
        open = false;
        hoveredQueue = -1;
        queueHitboxes.clear();
        closeBounds.setBounds(0, 0, 0, 0);
    }

    public boolean isOpen()
    {
        return open;
    }
    @Override
    public MouseEvent mouseEntered(MouseEvent event)
    {
        return mouseMoved(event);
    }
    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!open || !matchmaking.isLobbyOpen())
        {
            return null;
        }

        int[][] queues = ChessMatchmakingService.queuePresets();
        int height = overlayHeight();
        graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        graphics.setColor(BACKGROUND);
        graphics.fillRoundRect(0, 0, WIDTH, height, 10, 10);
        graphics.setColor(BORDER);
        graphics.drawRoundRect(0, 0, WIDTH - 1, height - 1, 10, 10);

        graphics.setColor(HEADER);
        graphics.fillRoundRect(1, 1, WIDTH - 2, HEADER_HEIGHT, 9, 9);
        graphics.fillRect(1, HEADER_HEIGHT - 9, WIDTH - 2, 10);

        graphics.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 13));
        graphics.setColor(TEXT);
        drawCentered(graphics, "VARROCK CHESS CLUB", 0, 6, WIDTH, 20);
        graphics.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 10));
        graphics.setColor(MUTED);
        drawCentered(graphics, "UNRATED QUICK MATCH", 0, 26, WIDTH, 16);

        queueHitboxes.clear();
        int y = HEADER_HEIGHT + PADDING;
        for (int i = 0; i < queues.length; i++)
        {
            int minutes = queues[i][0];
            int increment = queues[i][1];
            Rectangle rowBounds = new Rectangle(PADDING, y, WIDTH - PADDING * 2, ROW_HEIGHT);
            queueHitboxes.add(new QueueHitbox(rowBounds, minutes, increment));

            boolean selected = matchmaking.isSelectedQueue(minutes, increment);
            graphics.setColor(selected ? ROW_SELECTED : (hoveredQueue == i ? ROW_HOVER : ROW));
            graphics.fillRoundRect(rowBounds.x, rowBounds.y, rowBounds.width, rowBounds.height, 6, 6);
            graphics.setColor(selected ? ACCENT : new Color(76, 76, 76));
            graphics.drawRoundRect(rowBounds.x, rowBounds.y, rowBounds.width - 1, rowBounds.height - 1, 6, 6);

            graphics.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 12));
            graphics.setColor(TEXT);
            graphics.drawString(minutes + "+" + increment, rowBounds.x + 10, rowBounds.y + 18);

            int count = matchmaking.getQueueCount(minutes, increment);
            String countText = count == 1 ? "1 waiting" : count + " waiting";
            graphics.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 11));
            graphics.setColor(count > 0 ? SUCCESS : MUTED);
            FontMetrics metrics = graphics.getFontMetrics();
            graphics.drawString(
                countText,
                rowBounds.x + rowBounds.width - metrics.stringWidth(countText) - 10,
                rowBounds.y + 18);

            y += ROW_HEIGHT + ROW_GAP;
        }

        int footerY = y + 3;
        graphics.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 10));
        graphics.setColor(matchmaking.isConnecting() ? ACCENT : MUTED);
        drawCentered(graphics, statusText(), PADDING, footerY, WIDTH - PADDING * 2, 18);

        closeBounds.setBounds(PADDING, footerY + 22, WIDTH - PADDING * 2, 25);
        graphics.setColor(new Color(83, 43, 43, 245));
        graphics.fillRoundRect(closeBounds.x, closeBounds.y, closeBounds.width, closeBounds.height, 6, 6);
        graphics.setColor(DANGER);
        graphics.drawRoundRect(closeBounds.x, closeBounds.y, closeBounds.width - 1, closeBounds.height - 1, 6, 6);
        graphics.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 11));
        graphics.setColor(TEXT);
        drawCentered(graphics, "Leave lobby", closeBounds.x, closeBounds.y, closeBounds.width, closeBounds.height);

        return new Dimension(WIDTH, height);
    }

    @Override
    public MouseEvent mousePressed(MouseEvent event)
    {
        if (!isInsideOverlay(event))
        {
            return event;
        }

        consumingMouseSequence = true;
        event.consume();
        if (!SwingUtilities.isLeftMouseButton(event))
        {
            return event;
        }

        int localX = event.getX() - getBounds().x;
        int localY = event.getY() - getBounds().y;
        if (closeBounds.contains(localX, localY))
        {
            clientThread.invokeLater(() ->
            {
                matchmaking.closeLobby();
                close();
            });
            return event;
        }

        if (matchmaking.isConnecting())
        {
            return event;
        }

        for (QueueHitbox hitbox : queueHitboxes)
        {
            if (!hitbox.bounds.contains(localX, localY))
            {
                continue;
            }

            int minutes = hitbox.minutes;
            int increment = hitbox.increment;
            clientThread.invokeLater(() ->
            {
                if (matchmaking.isSelectedQueue(minutes, increment))
                {
                    matchmaking.cancelQueue();
                    return;
                }

                try
                {
                    matchmaking.joinQueue(minutes, increment);
                }
                catch (IllegalArgumentException | IllegalStateException ignored)
                {

                }
            });
            return event;
        }
        return event;
    }

    @Override
    public MouseEvent mouseReleased(MouseEvent event)
    {
        if (consumingMouseSequence || isInsideOverlay(event))
        {
            event.consume();
            SwingUtilities.invokeLater(() -> consumingMouseSequence = false);
        }
        return event;
    }

    @Override
    public MouseEvent mouseClicked(MouseEvent event)
    {
        if (consumingMouseSequence || isInsideOverlay(event))
        {
            event.consume();
        }
        return event;
    }

    @Override
    public MouseEvent mouseDragged(MouseEvent event)
    {
        if (consumingMouseSequence || isInsideOverlay(event))
        {
            event.consume();
        }
        return event;
    }

    @Override
    public MouseEvent mouseMoved(MouseEvent event)
    {
        hoveredQueue = -1;
        if (!isInsideOverlay(event))
        {
            return event;
        }

        int localX = event.getX() - getBounds().x;
        int localY = event.getY() - getBounds().y;
        for (int i = 0; i < queueHitboxes.size(); i++)
        {
            if (queueHitboxes.get(i).bounds.contains(localX, localY))
            {
                hoveredQueue = i;
                break;
            }
        }
        return event;
    }

    @Override
    public MouseEvent mouseExited(MouseEvent event)
    {
        hoveredQueue = -1;
        return event;
    }

    private boolean isInsideOverlay(MouseEvent event)
    {
        return open && matchmaking.isLobbyOpen() && getBounds().contains(event.getPoint());
    }

    private String statusText()
    {
        if (matchmaking.isConnecting())
        {
            return "Opponent found — connecting…";
        }
        if (matchmaking.isSearching())
        {
            return "Searching " + formatElapsed(matchmaking.getSearchElapsedSeconds())
                + " — click the selected queue to cancel";
        }
        return "Choose a time control to enter the queue";
    }

    private static String formatElapsed(long seconds)
    {
        long safe = Math.max(0L, seconds);
        return String.format("%d:%02d", safe / 60L, safe % 60L);
    }

    private static int overlayHeight()
    {
        int rows = ChessMatchmakingService.queuePresets().length;
        return HEADER_HEIGHT + PADDING + rows * ROW_HEIGHT + Math.max(0, rows - 1) * ROW_GAP + FOOTER_HEIGHT;
    }

    private static int clamp(int value, int min, int max)
    {
        return Math.max(min, Math.min(max, value));
    }

    private static void drawCentered(Graphics2D graphics, String text, int x, int y, int width, int height)
    {
        FontMetrics metrics = graphics.getFontMetrics();
        int textX = x + (width - metrics.stringWidth(text)) / 2;
        int textY = y + (height - metrics.getHeight()) / 2 + metrics.getAscent();
        graphics.drawString(text, textX, textY);
    }

    private static final class QueueHitbox
    {
        private final Rectangle bounds;
        private final int minutes;
        private final int increment;

        private QueueHitbox(Rectangle bounds, int minutes, int increment)
        {
            this.bounds = bounds;
            this.minutes = minutes;
            this.increment = increment;
        }
    }
}

package com.playercoder1.ui;

import com.playercoder1.chess.ChessColor;
import com.playercoder1.chess.ChessMultiplayerService;
import com.playercoder1.chess.LocalChessController;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.event.MouseEvent;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.client.input.MouseListener;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;


@Singleton
public final class ChessMatchControlsOverlay extends Overlay implements MouseListener
{
    private enum PendingAction
    {
        NONE,
        RESIGN,
        LEAVE
    }

    private static final int WIDTH = 278;
    private static final int HEIGHT_ACTIVE = 92;
    private static final int HEIGHT_FINISHED = 92;
    private static final int PADDING = 8;
    private static final int HEADER_HEIGHT = 23;
    private static final int DETAIL_HEIGHT = 22;
    private static final int BUTTON_HEIGHT = 29;
    private static final int BUTTON_GAP = 5;
    private static final long CONFIRM_MILLIS = 3_500L;

    private static final Color BACKGROUND = new Color(23, 23, 23, 242);
    private static final Color BORDER = new Color(190, 145, 68);
    private static final Color HEADER = new Color(31, 31, 31, 248);
    private static final Color BUTTON = new Color(67, 67, 67);
    private static final Color BUTTON_HOVER = new Color(82, 82, 82);
    private static final Color PRIMARY = new Color(173, 126, 45);
    private static final Color PRIMARY_HOVER = new Color(194, 144, 53);
    private static final Color DANGER = new Color(128, 58, 56);
    private static final Color DANGER_HOVER = new Color(153, 68, 64);
    private static final Color DISABLED = new Color(45, 45, 45);
    private static final Color MUTED = new Color(190, 190, 190);
    private static final Color SUCCESS = new Color(102, 181, 100);
    private static final Color WARNING = new Color(222, 172, 76);

    private final Client client;
    private final ChessMultiplayerService multiplayer;
    private final LocalChessController controller;
    private final ChessBoardOverlay boardOverlay;

    private final Rectangle firstButton = new Rectangle();
    private final Rectangle secondButton = new Rectangle();
    private final Rectangle thirdButton = new Rectangle();

    private boolean visible;
    private boolean consumingMouseSequence;
    private int hoveredButton;
    private PendingAction pendingAction = PendingAction.NONE;
    private long confirmUntilMillis;

    @Inject
    public ChessMatchControlsOverlay(
            Client client,
            ChessMultiplayerService multiplayer,
            LocalChessController controller,
            ChessBoardOverlay boardOverlay)
    {
        this.client = client;
        this.multiplayer = multiplayer;
        this.controller = controller;
        this.boardOverlay = boardOverlay;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
        setPriority(PRIORITY_HIGH);
        setMovable(true);
        setResettable(true);
        setSnappable(true);
        setPreferredLocation(new Point(28, 438));
        setPreferredSize(new Dimension(WIDTH, HEIGHT_ACTIVE));
    }

    @Override
    public String getName()
    {
        return "Chess Match Controls";
    }

    public void showForMatch()
    {
        if (!visible)
        {
            placeNearBoard();
        }
        setVisible(true);
    }

    private void placeNearBoard()
    {
        Point boardLocation = boardOverlay.getPreferredLocation();
        Dimension boardSize = boardOverlay.getPreferredSize();
        int canvasWidth = Math.max(320, client.getCanvasWidth());
        int canvasHeight = Math.max(320, client.getCanvasHeight());

        int boardX = boardLocation == null ? 28 : boardLocation.x;
        int boardY = boardLocation == null ? 28 : boardLocation.y;
        int boardWidth = boardSize == null ? 276 : boardSize.width;
        int boardHeight = boardSize == null ? 398 : boardSize.height;

        int x = boardX;
        int y = boardY + boardHeight + 6;
        if (y + HEIGHT_ACTIVE > canvasHeight - 12)
        {
            x = boardX + boardWidth + 6;
            y = boardY;
        }
        if (x + WIDTH > canvasWidth - 12 || y + HEIGHT_ACTIVE > canvasHeight - 12)
        {
            x = Math.max(12, canvasWidth - WIDTH - 12);
            y = Math.max(12, canvasHeight - HEIGHT_ACTIVE - 12);
        }

        setPreferredLocation(new Point(Math.max(12, x), Math.max(12, y)));
        revalidate();
    }

    public void setVisible(boolean visible)
    {
        this.visible = visible;
        if (!visible)
        {
            hoveredButton = 0;
            clearPendingAction();
        }
    }

    public boolean isVisible()
    {
        return visible;
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!visible || !boardOverlay.isVisible() || !multiplayer.isPlayingOnline())
        {
            return null;
        }

        expireConfirmationIfNeeded();

        boolean finished = controller.getGame().getStatus().isFinished();
        int height = finished ? HEIGHT_FINISHED : HEIGHT_ACTIVE;
        setPreferredSize(new Dimension(WIDTH, height));

        Graphics2D g = (Graphics2D) graphics.create();
        try
        {
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

            g.setColor(BACKGROUND);
            g.fillRoundRect(0, 0, WIDTH, height, 10, 10);
            g.setColor(BORDER);
            g.setStroke(new BasicStroke(1.5f));
            g.drawRoundRect(1, 1, WIDTH - 2, height - 2, 10, 10);

            g.setColor(HEADER);
            g.fillRoundRect(PADDING, PADDING, WIDTH - PADDING * 2, HEADER_HEIGHT, 6, 6);
            g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 12));
            g.setColor(Color.WHITE);
            drawCentered(g, titleText(), PADDING, PADDING, WIDTH - PADDING * 2, HEADER_HEIGHT);

            int detailY = PADDING + HEADER_HEIGHT;
            g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 10));
            g.setColor(multiplayer.isOpponentConnected() ? SUCCESS : WARNING);
            drawCentered(g, detailText(), PADDING, detailY, WIDTH - PADDING * 2, DETAIL_HEIGHT);

            int buttonY = detailY + DETAIL_HEIGHT;
            if (finished)
            {
                drawFinishedButtons(g, buttonY);
            }
            else
            {
                drawActiveButtons(g, buttonY);
            }
        }
        finally
        {
            g.dispose();
        }

        return new Dimension(WIDTH, height);
    }

    private void drawActiveButtons(Graphics2D g, int y)
    {
        int available = WIDTH - PADDING * 2;
        int buttonWidth = (available - BUTTON_GAP * 2) / 3;
        firstButton.setBounds(PADDING, y, buttonWidth, BUTTON_HEIGHT);
        secondButton.setBounds(PADDING + buttonWidth + BUTTON_GAP, y, buttonWidth, BUTTON_HEIGHT);
        thirdButton.setBounds(PADDING + (buttonWidth + BUTTON_GAP) * 2, y,
                available - buttonWidth * 2 - BUTTON_GAP * 2, BUTTON_HEIGHT);

        boolean canAct = multiplayer.canLocalPlayerAct();
        drawButton(g, firstButton, drawActionText(), 1, canAct, false, false);
        drawButton(g, secondButton, pendingAction == PendingAction.RESIGN ? "Confirm" : "Resign",
                2, canAct, false, true);
        drawButton(g, thirdButton, pendingAction == PendingAction.LEAVE ? "Confirm" : "Leave",
                3, true, false, true);
    }

    private void drawFinishedButtons(Graphics2D g, int y)
    {
        int available = WIDTH - PADDING * 2;
        int buttonWidth = (available - BUTTON_GAP) / 2;
        firstButton.setBounds(PADDING, y, buttonWidth, BUTTON_HEIGHT);
        secondButton.setBounds(PADDING + buttonWidth + BUTTON_GAP, y,
                available - buttonWidth - BUTTON_GAP, BUTTON_HEIGHT);
        thirdButton.setBounds(0, 0, 0, 0);

        boolean rematchEnabled = multiplayer.isOpponentConnected()
                && !multiplayer.isRematchRequestedByLocalPlayer();
        drawButton(g, firstButton, rematchText(), 1, rematchEnabled, true, false);
        drawButton(g, secondButton, pendingAction == PendingAction.LEAVE ? "Confirm leave" : "Leave match",
                2, true, false, true);
    }

    private void drawButton(
            Graphics2D g,
            Rectangle bounds,
            String text,
            int index,
            boolean enabled,
            boolean primary,
            boolean danger)
    {
        Color base;
        Color hover;
        if (!enabled)
        {
            base = DISABLED;
            hover = DISABLED;
        }
        else if (danger)
        {
            base = DANGER;
            hover = DANGER_HOVER;
        }
        else if (primary)
        {
            base = PRIMARY;
            hover = PRIMARY_HOVER;
        }
        else
        {
            base = BUTTON;
            hover = BUTTON_HOVER;
        }

        g.setColor(enabled && hoveredButton == index ? hover : base);
        g.fillRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, 5, 5);
        g.setColor(enabled ? new Color(215, 215, 215) : new Color(110, 110, 110));
        g.drawRoundRect(bounds.x, bounds.y, bounds.width, bounds.height, 5, 5);
        g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 10));
        g.setColor(enabled ? Color.WHITE : new Color(145, 145, 145));
        drawCenteredEllipsized(g, text, bounds.x + 2, bounds.y, bounds.width - 4, bounds.height);
    }

    private String titleText()
    {
        String kind = multiplayer.isMatchmade() ? "Quick Match" : "Private Match";
        return kind + "  " + multiplayer.getInitialMinutes() + "+" + multiplayer.getIncrementSeconds();
    }

    private String detailText()
    {
        ChessColor local = multiplayer.getLocalColor();
        String side = local == null ? "Online game" : "Playing " + local.displayName();
        return side + (multiplayer.isOpponentConnected() ? "  •  Opponent connected" : "  •  Reconnecting…");
    }

    private String drawActionText()
    {
        ChessColor offeredBy = controller.getDrawOfferedBy();
        ChessColor local = multiplayer.getLocalColor();
        if (offeredBy == null || local == null)
        {
            return "Offer draw";
        }
        return offeredBy == local ? "Cancel draw" : "Accept draw";
    }

    private String rematchText()
    {
        if (multiplayer.isRematchRequestedByLocalPlayer())
        {
            return "Rematch requested";
        }
        if (multiplayer.isRematchRequestedByOpponent())
        {
            return "Accept rematch";
        }
        return "Rematch";
    }

    @Override
    public MouseEvent mousePressed(MouseEvent event)
    {
        if (!isInside(event))
        {
            return event;
        }

        consumingMouseSequence = true;
        event.consume();
        if (!SwingUtilities.isLeftMouseButton(event))
        {
            return event;
        }

        int localX = event.getX() - getBounds().x;
        int localY = event.getY() - getBounds().y;
        boolean finished = controller.getGame().getStatus().isFinished();

        if (finished)
        {
            if (firstButton.contains(localX, localY))
            {
                if (!multiplayer.isRematchRequestedByLocalPlayer() && multiplayer.isOpponentConnected())
                {
                    clearPendingAction();
                    multiplayer.requestOrAcceptRematch();
                }
            }
            else if (secondButton.contains(localX, localY))
            {
                confirmOrExecuteLeave();
            }
            return event;
        }

        if (firstButton.contains(localX, localY) && multiplayer.canLocalPlayerAct())
        {
            clearPendingAction();
            multiplayer.offerAcceptOrCancelDraw();
        }
        else if (secondButton.contains(localX, localY) && multiplayer.canLocalPlayerAct())
        {
            confirmOrExecuteResign();
        }
        else if (thirdButton.contains(localX, localY))
        {
            confirmOrExecuteLeave();
        }
        return event;
    }

    private void confirmOrExecuteResign()
    {
        if (isConfirmed(PendingAction.RESIGN))
        {
            clearPendingAction();
            multiplayer.resign();
            return;
        }
        arm(PendingAction.RESIGN);
    }

    private void confirmOrExecuteLeave()
    {
        if (isConfirmed(PendingAction.LEAVE))
        {
            clearPendingAction();
            multiplayer.leaveMatch();
            boardOverlay.setVisible(false);
            setVisible(false);
            return;
        }
        arm(PendingAction.LEAVE);
    }

    private void arm(PendingAction action)
    {
        pendingAction = action;
        confirmUntilMillis = System.currentTimeMillis() + CONFIRM_MILLIS;
    }

    private boolean isConfirmed(PendingAction action)
    {
        return pendingAction == action && System.currentTimeMillis() <= confirmUntilMillis;
    }

    private void expireConfirmationIfNeeded()
    {
        if (pendingAction != PendingAction.NONE && System.currentTimeMillis() > confirmUntilMillis)
        {
            clearPendingAction();
        }
    }

    private void clearPendingAction()
    {
        pendingAction = PendingAction.NONE;
        confirmUntilMillis = 0L;
    }

    @Override
    public MouseEvent mouseReleased(MouseEvent event)
    {
        if (consumingMouseSequence || isInside(event))
        {
            event.consume();
            SwingUtilities.invokeLater(() -> consumingMouseSequence = false);
        }
        return event;
    }

    @Override
    public MouseEvent mouseClicked(MouseEvent event)
    {
        if (consumingMouseSequence || isInside(event))
        {
            event.consume();
        }
        return event;
    }

    @Override
    public MouseEvent mouseDragged(MouseEvent event)
    {
        if (consumingMouseSequence || isInside(event))
        {
            event.consume();
        }
        return event;
    }

    @Override
    public MouseEvent mouseMoved(MouseEvent event)
    {
        if (!isInside(event))
        {
            hoveredButton = 0;
            return event;
        }

        int localX = event.getX() - getBounds().x;
        int localY = event.getY() - getBounds().y;
        if (firstButton.contains(localX, localY))
        {
            hoveredButton = 1;
        }
        else if (secondButton.contains(localX, localY))
        {
            hoveredButton = 2;
        }
        else if (thirdButton.contains(localX, localY))
        {
            hoveredButton = 3;
        }
        else
        {
            hoveredButton = 0;
        }
        return event;
    }

    @Override
    public MouseEvent mouseEntered(MouseEvent event)
    {
        return mouseMoved(event);
    }

    @Override
    public MouseEvent mouseExited(MouseEvent event)
    {
        hoveredButton = 0;
        return event;
    }

    private boolean isInside(MouseEvent event)
    {
        return visible && boardOverlay.isVisible()
                && multiplayer.isPlayingOnline() && getBounds().contains(event.getPoint());
    }

    private static void drawCentered(Graphics2D g, String text, int x, int y, int width, int height)
    {
        FontMetrics metrics = g.getFontMetrics();
        int textX = x + (width - metrics.stringWidth(text)) / 2;
        int textY = y + (height - metrics.getHeight()) / 2 + metrics.getAscent();
        g.drawString(text, textX, textY);
    }

    private static void drawCenteredEllipsized(
            Graphics2D g,
            String text,
            int x,
            int y,
            int width,
            int height)
    {
        FontMetrics metrics = g.getFontMetrics();
        String value = text == null ? "" : text;
        if (metrics.stringWidth(value) > width)
        {
            String suffix = "…";
            while (!value.isEmpty() && metrics.stringWidth(value + suffix) > width)
            {
                value = value.substring(0, value.length() - 1);
            }
            value += suffix;
        }
        drawCentered(g, value, x, y, width, height);
    }
}

package com.playercoder1.ui;

import com.playercoder1.chess.ChessColor;
import com.playercoder1.chess.ChessGame;
import com.playercoder1.chess.ChessGameListener;
import com.playercoder1.chess.ChessMultiplayerService;
import com.playercoder1.chess.LocalChessController;
import com.playercoder1.chess.Move;
import com.playercoder1.chess.Piece;
import com.playercoder1.chess.PieceType;
import com.playercoder1.chess.Square;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridLayout;
import java.awt.Insets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.SwingConstants;

/** Compact interactive board used inside the RuneLite sidebar. */
@SuppressWarnings("serial")
public final class ChessBoardPanel extends JPanel implements ChessGameListener
{
    private static final Color LIGHT_SQUARE = new Color(181, 154, 107);
    private static final Color DARK_SQUARE = new Color(101, 73, 49);
    private static final Color SELECTED_SQUARE = new Color(214, 179, 67);
    private static final Color LEGAL_MOVE_SQUARE = new Color(120, 142, 70);
    private static final Color LAST_MOVE_SQUARE = new Color(153, 132, 62);

    private final LocalChessController controller;
    private final ChessMultiplayerService multiplayer;
    private final JButton[] buttons = new JButton[Square.BOARD_SIZE];
    private int selectedSquare = -1;
    private boolean flipped;

    public ChessBoardPanel(LocalChessController controller, ChessMultiplayerService multiplayer)
    {
        this.controller = controller;
        this.multiplayer = multiplayer;
        controller.addListener(this);

        setLayout(new GridLayout(8, 8, 0, 0));
        setPreferredSize(new Dimension(216, 216));
        setMaximumSize(new Dimension(216, 216));
        setBorder(BorderFactory.createLineBorder(Color.BLACK));

        Font fallbackFont = new Font(Font.SERIF, Font.PLAIN, 23);
        for (int displayIndex = 0; displayIndex < Square.BOARD_SIZE; displayIndex++)
        {
            JButton button = new JButton();
            button.setFont(fallbackFont);
            button.setHorizontalAlignment(SwingConstants.CENTER);
            button.setVerticalAlignment(SwingConstants.CENTER);
            button.setFocusPainted(false);
            button.setBorderPainted(false);
            button.setOpaque(true);
            button.setMargin(new Insets(0, 0, 0, 0));
            button.setFocusable(false);
            final int clickedDisplayIndex = displayIndex;
            button.addActionListener(event -> clickDisplaySquare(clickedDisplayIndex));
            buttons[displayIndex] = button;
            add(button);
        }
        refresh();
    }

    public void setFlipped(boolean flipped)
    {
        if (this.flipped == flipped)
        {
            return;
        }

        this.flipped = flipped;
        selectedSquare = -1;
        refresh();
    }

    public boolean isFlipped()
    {
        return flipped;
    }

    public void clearSelection()
    {
        selectedSquare = -1;
        refresh();
    }

    @Override
    public void onGameChanged()
    {
        if (controller.getGame().getStatus().isFinished())
        {
            selectedSquare = -1;
        }
        refresh();
    }

    private void clickDisplaySquare(int displayIndex)
    {
        ChessGame game = controller.getGame();
        if (game.getStatus().isFinished())
        {
            return;
        }

        int square = boardSquareForDisplayIndex(displayIndex);
        Piece clickedPiece = game.getPiece(square);
        ChessColor sideToMove = game.getSideToMove();

        if (selectedSquare < 0)
        {
            if (clickedPiece != null
                && clickedPiece.getColor() == sideToMove
                && multiplayer.canSelectPiece(clickedPiece.getColor()))
            {
                selectedSquare = square;
                refresh();
            }
            return;
        }

        if (square == selectedSquare)
        {
            selectedSquare = -1;
            refresh();
            return;
        }

        if (clickedPiece != null && clickedPiece.getColor() == sideToMove)
        {
            if (multiplayer.canSelectPiece(clickedPiece.getColor()))
            {
                selectedSquare = square;
                refresh();
            }
            return;
        }

        List<Move> matchingMoves = new ArrayList<>();
        for (Move move : game.getLegalMovesFrom(selectedSquare))
        {
            if (move.getTo() == square)
            {
                matchingMoves.add(move);
            }
        }

        if (matchingMoves.isEmpty())
        {
            return;
        }

        Move chosenMove = choosePromotionIfNeeded(matchingMoves);
        if (chosenMove != null && multiplayer.playMove(chosenMove))
        {
            selectedSquare = -1;
        }
        refresh();
    }

    private Move choosePromotionIfNeeded(List<Move> matchingMoves)
    {
        if (matchingMoves.size() == 1 && matchingMoves.get(0).getPromotion() == null)
        {
            return matchingMoves.get(0);
        }

        Object[] options = {"Queen", "Rook", "Bishop", "Knight"};
        int choice = JOptionPane.showOptionDialog(
            this,
            "Choose a promotion piece",
            "Pawn promotion",
            JOptionPane.DEFAULT_OPTION,
            JOptionPane.PLAIN_MESSAGE,
            null,
            options,
            options[0]);

        PieceType type;
        switch (choice)
        {
            case 1:
                type = PieceType.ROOK;
                break;
            case 2:
                type = PieceType.BISHOP;
                break;
            case 3:
                type = PieceType.KNIGHT;
                break;
            case 0:
                type = PieceType.QUEEN;
                break;
            default:
                return null;
        }

        for (Move move : matchingMoves)
        {
            if (move.getPromotion() == type)
            {
                return move;
            }
        }
        return null;
    }

    private void refresh()
    {
        ChessGame game = controller.getGame();
        List<Move> legalMoves = selectedSquare < 0
            ? Collections.emptyList()
            : game.getLegalMovesFrom(selectedSquare);
        Move lastMove = game.getLastMove();

        for (int displayIndex = 0; displayIndex < Square.BOARD_SIZE; displayIndex++)
        {
            int square = boardSquareForDisplayIndex(displayIndex);
            int file = Square.file(square);
            int rank = Square.rank(square);
            JButton button = buttons[displayIndex];
            Piece piece = game.getPiece(square);

            ImageIcon icon = ChessPieceImages.icon(piece, 25);
            button.setIcon(icon);
            button.setText(piece == null || icon != null ? "" : piece.symbol());
            button.setToolTipText(Square.toAlgebraic(square));

            Color background = ((file + rank) & 1) == 0 ? DARK_SQUARE : LIGHT_SQUARE;
            if (lastMove != null && (lastMove.getFrom() == square || lastMove.getTo() == square))
            {
                background = LAST_MOVE_SQUARE;
            }
            for (Move move : legalMoves)
            {
                if (move.getTo() == square)
                {
                    background = LEGAL_MOVE_SQUARE;
                    break;
                }
            }
            if (selectedSquare == square)
            {
                background = SELECTED_SQUARE;
            }
            button.setBackground(background);
        }
        repaint();
    }

    private int boardSquareForDisplayIndex(int displayIndex)
    {
        int row = displayIndex / 8;
        int column = displayIndex % 8;
        int file = flipped ? 7 - column : column;
        int rank = flipped ? row : 7 - row;
        return Square.of(file, rank);
    }
}

package com.playercoder1.ui;

